import io
import json
import tarfile

REQUIRED = ("audio_filepath", "duration", "text")
NEMO_MEMBERS = ("config.yaml", "model_weights.ckpt", "tokenizer.txt")


def parse_manifest(text):
    entries = []
    for number, line in enumerate(text.splitlines(), start=1):
        if not line.strip():
            continue
        try:
            entry = json.loads(line)
        except ValueError as exc:
            raise ValueError(f"line {number}: not valid JSON ({exc})") from None
        if not isinstance(entry, dict):
            raise ValueError(f"line {number}: expected an object")
        for key in REQUIRED:
            if key not in entry:
                raise ValueError(f"line {number}: missing {key!r}")
        if not isinstance(entry["audio_filepath"], str) or not entry["audio_filepath"]:
            raise ValueError(f"line {number}: audio_filepath must be a non-empty string")
        duration = entry["duration"]
        if isinstance(duration, bool) or not isinstance(duration, (int, float)):
            raise ValueError(f"line {number}: duration must be a number")
        if duration <= 0:
            raise ValueError(f"line {number}: duration must be positive")
        if not isinstance(entry["text"], str):
            raise ValueError(f"line {number}: text must be a string")
        entries.append(entry)
    return entries


def total_duration(entries):
    return sum(entry["duration"] for entry in entries)


def make_batches(entries, batch_size):
    if batch_size < 1:
        raise ValueError("batch size must be at least 1")
    return [entries[start:start + batch_size]
            for start in range(0, len(entries), batch_size)]


def padded_cost(batch):
    if not batch:
        return 0.0
    longest = max(entry["duration"] for entry in batch)
    return longest * len(batch)


def padding_waste(batches):
    return sum(padded_cost(batch) - total_duration(batch) for batch in batches)


def sort_by_duration(entries):
    return sorted(entries, key=lambda entry: entry["duration"])


def write_nemo(config, weights, tokenizer):
    buffer = io.BytesIO()
    payload = {"config.yaml": config.encode(), "model_weights.ckpt": weights,
               "tokenizer.txt": tokenizer.encode()}
    with tarfile.open(fileobj=buffer, mode="w") as archive:
        for name in NEMO_MEMBERS:
            data = payload[name]
            info = tarfile.TarInfo(name)
            info.size = len(data)
            archive.addfile(info, io.BytesIO(data))
    return buffer.getvalue()


def read_nemo(blob):
    with tarfile.open(fileobj=io.BytesIO(blob), mode="r") as archive:
        names = archive.getnames()
        missing = [name for name in NEMO_MEMBERS if name not in names]
        if missing:
            raise ValueError(
                f"not a restorable checkpoint: missing {', '.join(missing)}")
        return {
            "config": archive.extractfile("config.yaml").read().decode(),
            "weights": archive.extractfile("model_weights.ckpt").read(),
            "tokenizer": archive.extractfile("tokenizer.txt").read().decode(),
        }
